def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    out_rows = rows // 3
    out_cols = cols // 3

    result = []

    for r in range(out_rows):
        row = []
        for c in range(out_cols):
            colors = {}

            for dr in range(3):
                for dc in range(3):
                    rr = r * 3 + dr
                    cc = c * 3 + dc

                    if rr < rows and cc < cols:
                        color = grid[rr][cc]
                        colors[color] = colors.get(color, 0) + 1

            max_color = max(colors.keys(), key=lambda x: colors[x])
            row.append(max_color)

        result.append(row)

    return result
